style.css:
/* PINK POLKADOT BACKGROUND */

html,
body {
    background-color: #ffedf0 !important;

    background-image:
        radial-gradient(
            circle,
            #9b8588 7.5px,
            transparent 8px
        ),
        radial-gradient(
            circle,
            #9b8588 7.5px,
            transparent 8px
        ) !important;

    background-size: 84px 84px !important;
    background-position: 0 0, 42px 42px !important;
    background-attachment: fixed !important;
}

/* Keep website content readable */
body {
    background-repeat: repeat !important;
}
